function renderBase(){const p=L.find(x=>x[0]===selected)||L[0];$('simName').textContent=state.name||'New arrival';$('avatar').style.background=state.color||blank.color;$('simTag').textContent=(state.background?roleOf().label+' · ':'')+'Day '+state.day;$('levelLabel').textContent='LEVEL '+level();$('xpLabel').textContent=(state.xp%100)+' / 100 XP';$('xpBar').style.width=(state.xp%100)+'%';$('wallet').textContent='¥'+state.money.toLocaleString();$('clock').textContent=timeText();$('phoneTime').textContent=timeText();$('period').textContent=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][(state.day-1)%7]+' · Autumn';$('needsList').innerHTML=needs.map(k=>'<div class="need-row"><div class="need-copy"><span>'+icons[k]+' '+names[k]+'</span><span>'+state.needs[k]+'%</span></div><div class="need-track"><i class="'+(state.needs[k]<25?'low':'')+'" style="width:'+state.needs[k]+'%"></i></div></div>').join('');$('currentPlace').textContent=p[2];$('panelContent').innerHTML='<div class="place-hero"><span>'+p[3]+'</span><strong>'+p[1]+'</strong><small>'+p[2]+'</small></div><div class="panel-content"><p>'+p[6]+'</p><div class="activity-list">'+p[7].map((a,i)=>'<button class="activity-item" data-act="'+i+'"><span><b>'+a[0]+'</b><small>'+a[1]+'</small></span><span class="cost">'+(a[2]===0?'FREE':a[2]<0?'+¥'+(-a[2]):'¥'+a[2])+'</span></button>').join('')+'</div></div>';$('panelContent').querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>activity(p,+b.dataset.act));$('agenda').innerHTML=state.job?'<b>Next shift</b>'+(jobs.find(j=>j[0]===state.job)||jobs[0])[1]:'<b>No shift booked</b>Open your phone to find work.';$('mapPins').innerHTML=L.map(p=>'<button class="pin '+(p[0]===selected?'active':'')+'" data-pin="'+p[0]+'" style="left:'+p[4]+'%;top:'+p[5]+'%"><span class="pin-dot">'+p[3]+'</span><label>'+p[1]+'</label></button>').join('');$('mapPins').querySelectorAll('[data-pin]').forEach(b=>b.onclick=()=>select(b.dataset.pin));const pulses=[['☕','Café shift open','Two morning shifts are available near Heping.','Now · Heping'],['◎','Language exchange','Newcomers are meeting at EFH tonight.','18:30 · EFH'],['♨','Market question','What is the best winter food in Shenyang?','14 replies · Community'],['✺','Tonight in Shenyang','Open mic at Foreigners’ Night.','20:00 · Heping'],['↗','New opportunity','A startup is looking for English-speaking creators.','Today · Hunnan'],['♧','Weekend trip','Harbin is 60% booked for this weekend.','Travel board']];$('pulseGrid').innerHTML=pulses.map(x=>'<article class="pulse-card"><div class="pulse-icon">'+x[0]+'</div><strong>'+x[1]+'</strong><p>'+x[2]+'</p><small>'+x[3]+'</small></article>').join('')}
function arrive(id){if(!L.some(p=>p[0]===id))return;selected=id;state.place=id;if(!state.visited.includes(id))state.visited.push(id);save();render()}function select(id){if(!inCity(id))return toast('This venue is in '+placeCity[id]+'. Travel to '+placeCity[id]+' first.');if(window.ChinaLifeWorld?.busy)return toast('Finish your current action first.');if(!L.some(p=>p[0]===id))return toast('Choose a city venue.');if(id===state.place)return arrive(id);travelScreen(id)}function duration(text){const h=text.match(/(\d+)h/),m=text.match(/(\d+)m/);return (h?parseInt(h[1])*60:0)+(m?parseInt(m[1]):0)||60}function activity(p,i){if(!p||!Number.isInteger(i)||!p[7][i])return toast('Choose a valid activity.');if(p[0]!==state.place)return toast('Travel to this venue first.');if(cityContent.estates.some(h=>h.id===p[0])&&!isResidence(p[0]))return estateScreen(p[0]);if(p[0]==='cafe'&&i===0){if(state.job!=='cafe-job')return jobsDialog();return workShift('steady')}if(!clubOpen(p[0]))return toast(p[1]+' opens at '+String(clubHours[p[0]][0]).padStart(2,'0')+':00.');const key=p[0]+':'+i,a=p[7][i];if(a[2]<0&&state.paidActivities[key]===state.day)return toast('You have completed this paid gig today.');const req=a[1].match(/requires (\w+) (\d+)/);if(req&&(state.skills[req[1]]||1)<+req[2])return toast('Train '+req[1]+' to level '+req[2]+' first.');if(state.needs.energy<10&&p[0]!=='home')return toast('You need to rest at home first.');if(a[2]>0&&a[2]>state.money)return earnScreen('You need ¥'+(a[2]-state.money)+' more for '+a[0]+'.');if(!runningCallback&&window.ChinaLifeWorld)return sceneAction({index:i,label:a[0]},()=>activity(p,i));$('activityDialog').close();state.money-=a[2];if(a[2]<0)state.paidActivities[key]=state.day;state.stats.activities++;Object.entries(a[3]).forEach(x=>state.needs[x[0]]=Math.max(0,Math.min(100,state.needs[x[0]]+x[1])));if(isResidence(p[0])&&i===0&&state.upgrades.includes('bed'))state.needs.energy=Math.min(100,state.needs.energy+15);if(isResidence(p[0])&&i===1&&state.upgrades.includes('kitchen'))state.needs.hunger=Math.min(100,state.needs.hunger+10);advance(duration(a[1]));const train=a[1].match(/trains (\w+)/);if(train)gain(train[1],20);state.xp+=10;state.logs.unshift(a[4]);save();render();toast(a[4])}
function jobsDialog(){let h=jobs.map(j=>'<button class="choice-action" data-job="'+j[0]+'"><b>'+j[1]+'</b><span>'+j[2]+' · '+j[5]+'h · one shift per day</span><span>'+(j[6]?'Requires skill '+j[6]:'Entry level')+' · <strong>¥'+j[4]+'/shift</strong></span></button>').join('');$('activityContent').innerHTML='<div class="activity-panel"><span class="eyebrow">OPPORTUNITIES IN '+state.city.toUpperCase()+'</span><h2>Find work that fits your life.</h2><p class="lead">Jobs pay virtual yuan and build skills. Apply today, start tomorrow.</p>'+(state.job?action('currentJob','Your current job · work a shift','Travel to work and choose your pace'):'')+h+'</div>';if(!$('activityDialog').open)$('activityDialog').showModal();if($('currentJob'))$('currentJob').onclick=shiftScreen;$('activityContent').querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{const j=jobs.find(x=>x[0]===b.dataset.job);if(j[6]&&(!state.skills[j[3]]||state.skills[j[3]]<j[6]))return toast('Your '+j[3]+' skill is not high enough yet.');if(state.job===j[0])return toast('This is already your job. Open Your current job to work a shift.');state.job=j[0];state.jobStart=state.day+1;state.shifts=0;state.promotion=1;state.logs.unshift('You applied for '+j[1]+'. Your first shift starts tomorrow.');save();$('activityDialog').close();render();toast('Application sent')})}
