function walletSummary(){let assets=0,homes=0;for(const types of Object.values(state.propertyPortfolio||{}))for(const type of new Set(types)){const h=catalog.properties.find(p=>p.id===type);if(h){homes++;assets+=h.price}}for(const h of cityContent.estates)if(state.ownedHomes.includes(h.id)){homes++;assets+=h.price}for(const id of new Set(state.upgrades)){assets+=catalog.furniture.find(f=>f.id===id)?.price||0}const netWorth=Math.max(0,state.money)+assets;return {assets,homes,netWorth,tier:netWorth>=5000000?'Property magnate':netWorth>=1000000?'Millionaire':netWorth>=100000?'Established':'Building a life'}}
function walletScreen(){const s=walletSummary(),yuan=n=>'¥'+Number(n).toLocaleString(),name=escapeHTML(state.name);screen('Hafrik Life Wallet','Your money. Your progress. Your ChinaLife.', '<section class="bank-card" aria-label="ChinaLife wallet card"><div class="bank-card-top"><b>HAFRIK</b><span>LIFE WALLET · CNY</span></div><p class="bank-label">AVAILABLE BALANCE</p><div class="bank-amount">'+yuan(state.money)+'</div><div class="bank-card-bottom"><div><small>ACCOUNT HOLDER</small><strong>'+name+'</strong></div><span class="bank-tier">'+escapeHTML(s.tier)+'</span></div></section><div class="bank-metrics"><div><small>Net worth</small><b>'+yuan(s.netWorth)+'</b></div><div><small>Property portfolio</small><b>'+s.homes+' homes</b></div><div><small>Asset value</small><b>'+yuan(s.assets)+'</b></div></div><div class="bank-actions">'+action('walletSend','↗ Send money','Transfer virtual yuan to a player')+action('walletBrag','✦ Show off your wallet','Create a clean card to share')+action('walletHomes','⌂ My homes','View your property portfolio')+'</div><h3>Recent transfers</h3><div id="walletTransfers" class="bank-transfers">'+(window.ChinaLifeCloud?.signedIn?'Loading transfers…':'Sign in with Hafrik to see account transfers.')+'</div><div class="bank-rent"><span>Weekly rent</span><b>'+yuan(rentDue())+'</b><small>Next payment · day '+(state.day+(7-state.day%7))+ '</small></div>'+action('walletJob','Earn from a career','Apply for a job or work your next shift')+action('walletStudio','Grow a studio','Fulfil client orders and invest in upgrades'));$('walletSend').onclick=()=>{$('activityDialog').close();if(!window.ChinaLifeCloud?.signedIn){toast('Sign in with Hafrik to send money.');return window.ChinaLifeCloud?.open()}window.ChinaLifeSocial?.open('people');toast('Choose a player or friend, then tap Send money.')};$('walletBrag').onclick=walletShowcase;$('walletHomes').onclick=homesScreen;$('walletJob').onclick=()=>state.job?shiftScreen():jobsDialog();$('walletStudio').onclick=businessScreen;const container=$('walletTransfers'),account=window.ChinaLifeCloud?.playerId;if(window.ChinaLifeCloud?.signedIn&&window.ChinaLifeAuth)window.ChinaLifeAuth.request('/chinalife/transfers.php','GET').then(r=>{if(container!==$('walletTransfers')||account!==window.ChinaLifeCloud?.playerId)return;const transfers=(r.data||r).transfers;container.innerHTML=transfers.length?transfers.map(t=>{const sent=String(t.sender_id)===String(account);return '<div class="bank-transfer"><div><b>'+(sent?'Sent to ':'Received from ')+escapeHTML(String(sent?(t.recipient_name||t.recipient_id):(t.sender_name||t.sender_id)))+'</b><small>'+escapeHTML(t.created_at)+'</small></div><strong class="'+(sent?'outgoing':'incoming')+'">'+(sent?'−':'+')+yuan(t.amount)+'</strong></div>'}).join(''):'<p>No transfers yet. Your next connection starts here.</p>'}).catch(()=>{if(container===$('walletTransfers'))container.textContent='Transfers could not load. Reopen your wallet to try again.'})}
function walletShowcase(){const s=walletSummary(),text=state.name+' · ChinaLife\n'+s.tier+'\nWallet: ¥'+state.money.toLocaleString()+'\nNet worth: ¥'+s.netWorth.toLocaleString()+'\n'+s.homes+' homes · '+rankForWallet();screen('My ChinaLife','Built one day at a time.', '<section class="bank-card bank-showcase"><div class="bank-card-top"><b>HAFRIK</b><span>CHINALIFE</span></div><h3>'+escapeHTML(state.name)+'</h3><span class="bank-tier">'+escapeHTML(s.tier)+'</span><p class="bank-label">MY WALLET</p><div class="bank-amount">¥'+state.money.toLocaleString()+'</div><p>'+s.homes+' homes · '+escapeHTML(rankForWallet())+'</p><p>Net worth · ¥'+s.netWorth.toLocaleString()+'</p></section>'+action('walletCopy','Copy my brag card','Share the text with friends')+action('walletBack','Back to wallet','Balance, transfers and your homes'));$('walletCopy').onclick=async()=>{try{await window.navigator.clipboard.writeText(text);toast('Wallet brag card copied.')}catch{screen('Your brag card','Select and copy your card text.', '<textarea class="name-input bank-copy" readonly aria-label="Wallet brag card">'+escapeHTML(text)+'</textarea>')}};$('walletBack').onclick=walletScreen}
function rankForWallet(){return ranks[rankIndex(state.xp)][1]}

function settingsScreen(){const perm='Notification' in window?Notification.permission:'unsupported';screen('Make it yours','Your character saves automatically on this device.',action('notifySetting',perm==='granted'?'🔔 Notifications: on':'🔔 Turn on notifications',perm==='denied'?'Blocked in your browser settings':perm==='unsupported'?'Not supported on this browser':'Daily rewards, rank-ups and reminders')+action('motionSetting',state.reduceMotion?'Motion: reduced':'Motion: standard','Toggle character idle animation')+action('changeLook','Edit your character','Skin tone, hairstyle and outfit')+action('importSave','Import a save','Restore an exported character backup')+action('exportSave','Export your save','Download a backup of your character and progress')+action('gameHelp','How to play','Movement, activities and progression'));$('notifySetting').onclick=async()=>{if(!('Notification' in window))return toast('Notifications are not supported here.');const r=await Notification.requestPermission();if(r!=='granted'){toast('Notifications are off.');return settingsScreen()}let push='';try{push=await window.ChinaLifeCloud?.enablePush?.()}catch{}toast(push==='on'?'Notifications are on, even when the game is closed.':push==='signin'?'Notifications are on. Sign in with Hafrik to get daily reminders when the game is closed.':push==='unsupported'?'Notifications are on while the game is open. Install the app to get them when it is closed.':'Notifications are on.');settingsScreen()};$('changeLook').onclick=appearanceScreen;$('importSave').onclick=()=>{const input=document.createElement('input');input.type='file';input.accept='application/json,.json';input.onchange=async()=>{try{const file=input.files[0];if(!file||file.size>1000000)throw new Error('Choose a save file under 1 MB.');const restored=validateSave(JSON.parse(await file.text()));if(!confirm('Replace this device’s character with '+restored.name+'? Export your current save first if you want to keep it.'))return;state=restored;selected=state.place;ensure();finish('Character save restored.');settingsScreen()}catch(e){toast(e.message||'This save could not be imported.')}};input.click()};$('motionSetting').onclick=()=>{state.reduceMotion=!state.reduceMotion;save();settingsScreen()};$('exportSave').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='chinalife-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Character backup downloaded.')};$('gameHelp').onclick=()=>{$('activityDialog').close();$('helpDialog').showModal()}}

// Each role decides the starting spot, money and skill, and which phone apps come first.
const roles={
 Student:{label:'Student',icon:'🎓',pitch:'Study at a Shenyang university and build your campus life',tagline:'Classes, campus friends and part-time work.',money:3200,skill:'Study',home:'campus',focus:['story','skills','jobs','people','events']},
 Entrepreneur:{label:'Entrepreneur',icon:'🚀',pitch:'Start a business and grow your network',tagline:'Your business, deals and network.',money:8000,skill:'Network',home:'home',focus:['studio','people','events','wallet','skills']},
 Worker:{label:'Professional',icon:'💼',pitch:'Work a job and climb your career',tagline:'Shifts, promotions and payday.',money:3200,skill:'Digital',home:'home',focus:['jobs','skills','wallet','people','events']},
 Creator:{label:'Creator',icon:'🎥',pitch:'Make content and build an audience',tagline:'Your studio, audience and collabs.',money:3200,skill:'Creativity',home:'home',focus:['studio','events','people','travel','skills']},
 Tourist:{label:'Tourist',icon:'🧳',pitch:'Explore cities, food and culture',tagline:'Trips, food and places to see.',money:6000,skill:'Social',home:'home',focus:['travel','events','shop','people','wallet']}
};
const roleOf=()=>roles[state.background]||roles.Student;
// Ranks reward playing: XP from every activity raises your rank, each rank-up pays a reward,
// and opening the game on consecutive days builds a daily streak.
const dailyReady=()=>state.created&&state.lastVisit!==today(),dailyStreak=()=>{const y=new Date(Date.now()-864e5).toISOString().slice(0,10);return state.lastVisit===y?Math.min((state.streak||0)+1,7):1};
// Daily red envelope hunt: three 🧧 are hidden in Shenyang venues each real day (the same for
// every player). Each pays once; one in twenty is the ¥8,888 jackpot.
const treasureHints={market:'where people haggle over food',cafe:'where coffee is served',african:'where jollof is served',hotel:'where travellers sleep',night:'where people dance',blood:'where people dance',skylight:'high above the city',campus:'where students learn',university:'where students learn',liaoning:'where students learn',dongbei:'where students learn',ef:'where students learn',academy:'where people take courses',gym:'where people sweat',park:'among the trees',mall:'where people shop',plaza:'where players meet',church:'in a quiet place',business:'where founders pitch',station:'where trains leave',airport:'where planes take off'};
function dayHash(text){let h=2166136261;for(const c of text)h=Math.imul(h^c.charCodeAt(0),16777619);return h>>>0}
function treasures(day=today()){const pool=Object.keys(treasureHints).filter(id=>L.some(p=>p[0]===id)),picked=[];let h=dayHash(day);for(let n=0;n<200&&picked.length<3;n++){h=Math.imul(h^h>>>15,2246822519)+n>>>0;const id=pool[h%pool.length];if(!picked.includes(id))picked.push(id)}for(const id of pool)if(picked.length<3&&!picked.includes(id))picked.push(id);return picked.map((id,i)=>{const r=dayHash(day+id),jackpot=r%20===0;return {id,x:-5+(r%1000)/100,z:-2.5+((r>>>10)%600)/100,reward:jackpot?8888:[300,500,800,1200,2000][r%5],jackpot}})}
function huntState(){const day=today();if(state.treasures?.day!==day)state.treasures={day,found:[]};return state.treasures}
function treasureHere(id){if(!state.created||state.city!=='Shenyang')return null;const t=treasures().find(t=>t.id===id);return t&&!huntState().found.includes(id)?t:null}
function collectTreasure(id){const t=treasureHere(id);if(!t||state.place!==id)return false;huntState().found.push(id);state.treasureTotal=(state.treasureTotal||0)+1;const reward=t.reward*(festivalToday()?2:1);state.money+=reward;state.xp+=50;finish((t.jackpot?'🧧 JACKPOT! ':'🧧 You found a red envelope! ')+'+¥'+reward.toLocaleString()+(festivalToday()?' · festival double':'')+' · +50 XP');checkSecrets();return true}
function huntSummary(){const list=treasures(),found=huntState().found;return {found:found.length,total:list.length,hints:list.filter(t=>!found.includes(t.id)).map(t=>treasureHints[t.id])}}
function checkSecrets(force){if(!state.created)return;state.secrets=state.secrets||[];for(const [id,name,,reward,done] of secrets){if(state.secrets.includes(id)&&id!==force)continue;if(id!==force&&!done(state))continue;if(!state.secrets.includes(id))state.secrets.push(id);state.money+=reward;state.logs.unshift('Secret task unlocked: '+name+' · +¥'+reward.toLocaleString());save();setTimeout(()=>toast('🔓 Secret task: '+name+' · +¥'+reward.toLocaleString()),1600)}}
function huntScreen(){const h=huntSummary(),g=window.ChinaLifeCloud?.golden,fest=festivalToday();screen('🧧 Red envelope hunt',h.found+' of '+h.total+' found today · new envelopes every day',(fest?'<p class="festival-note">'+fest+' · red envelopes pay double today</p>':'')+(g?'<div class="golden-note"><b>🌟 Golden envelope · ¥'+g.reward.toLocaleString()+'</b><span>'+(g.found_by?'Found this week by '+escapeHTML(g.found_by)+(g.mine?' (you!)':''):'One per week · first finder wins · hidden '+escapeHTML(treasureHints[g.place]||'somewhere in Shenyang'))+'</span></div>':'<p class="fine-print">Sign in with Hafrik to hunt the weekly 🌟 golden envelope.</p>')+'<p>Envelopes are hidden inside Shenyang venues. Visit a place and look around the room for a glowing red envelope, then tap it.</p>'+(h.hints.length?'<h3>Hints</h3>'+h.hints.map(x=>'<p class="journal-item">One is hidden '+escapeHTML(x)+'.</p>').join(''):'<p><b>You found them all today.</b> Come back tomorrow.</p>')+'<h3>Secret tasks · '+(state.secrets||[]).length+'/'+secrets.length+'</h3><div class="rank-list">'+secrets.map(([id,name,how,reward])=>{const open=(state.secrets||[]).includes(id);return '<div class="'+(open?'reached':'')+'"><span>'+(open?'🔓':'🔒')+'</span><b>'+(open?name:'???')+'</b><small>'+(open?how:'Hidden')+' · ¥'+reward.toLocaleString()+'</small></div>'}).join('')+'</div>')}
// Survival: at zero energy or hunger the player faints and loses time, then can ask for food.
let fainting=false,lastWarn='';
function survival(){if(!state.created||fainting||window.ChinaLifeWorld?.busy)return;const n=state.needs;if(n.energy<=0||n.hunger<=0)return faint(n.hunger<=0?'hunger':'energy');const low=n.hunger<15?'hunger':n.energy<15?'energy':'';const key=low+state.day;if(low&&lastWarn!==key){lastWarn=key;setTimeout(()=>notify(low==='hunger'?'🍜 You are very hungry. Eat soon or you will faint.':'😴 You are exhausted. Rest soon or you will faint.',tasksScreen),900)}}
function faint(cause){fainting=true;advance(90);state.needs.energy=Math.max(state.needs.energy,20);state.needs.fun=Math.max(0,state.needs.fun-10);state.logs.unshift('You fainted from '+(cause==='hunger'?'hunger':'exhaustion')+'.');save();fainting=false;faintScreen(cause)}
function faintScreen(cause){const askable=state.foodHelpDay!==state.day;screen('😵 You fainted',(cause==='hunger'?'You went too long without food.':'You pushed yourself too hard.')+' You lost 90 minutes.',(state.needs.hunger<40?action('faintAsk',askable?'🙏 Ask for food':'🙏 Ask for food · used today',askable?'Free · once a day · +40 hunger':'Try again tomorrow')+action('faintBuy','🛵 Order food','Delivered to you in 30 minutes'):'')+action('faintHome','🏠 Go home and rest','Sleep restores your energy')+(state.money<25?action('faintEarn','💴 Make money','You are out of money'):''));
 if($('faintAsk'))$('faintAsk').onclick=()=>{if(state.foodHelpDay===state.day)return toast('Nobody can help again today.');state.foodHelpDay=state.day;state.needs.hunger=Math.min(100,state.needs.hunger+40);state.needs.social=Math.min(100,state.needs.social+5);finish('A kind stranger shared a bowl of dumplings with you.')};
 if($('faintBuy'))$('faintBuy').onclick=()=>deliveryScreen(true);
 $('faintHome').onclick=()=>{$('activityDialog').close();select('home')};if($('faintEarn'))$('faintEarn').onclick=()=>earnScreen()}
// Make money: quick phone gigs (once a day each) plus the job and office routes.
function earnScreen(reason){screen('💴 Make money',reason||'Pick a way to earn.',(state.job?action('earnShift','💼 Work your shift','Your job · pays every shift'):action('earnJob','💼 Find a job','Steady pay every day'))+gigs.map(([id,name,time,pay])=>action('gig-'+id,name+' · +¥'+pay,time+(state.gigs?.[id]===state.day?' · done today':' · now'))).join('')+action('earnOffice','🏢 Go to the office','Hunnan Startup Hub · meet clients and founders'));
 $(state.job?'earnShift':'earnJob').onclick=state.job?shiftScreen:jobsDialog;$('earnOffice').onclick=()=>{$('activityDialog').close();select('business')};
 gigs.forEach(([id,name,time,pay,energy,story])=>$('gig-'+id).onclick=()=>{state.gigs=state.gigs||{};if(state.gigs[id]===state.day)return toast('You already did this today.');if(state.needs.energy<energy+5)return toast('Rest first. You need more energy.');state.gigs[id]=state.day;state.money+=pay;state.needs.energy-=energy;state.needs.hunger=Math.max(0,state.needs.hunger-8);advance(duration(time));state.xp+=10;finish(story+' +¥'+pay);earnScreen()})}
// Today: short countdowns so players know what is due next.
function untilReset(){const now=new Date(),next=Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()+1),m=Math.max(0,Math.round((next-now)/6e4));return Math.floor(m/60)+'h '+m%60+'m'}
function todayTasks(){const list=[],n=state.needs;if(n.hunger<30)list.push(['🍜','Eat soon · hunger '+n.hunger+'% · order delivery']);if(n.energy<30)list.push(['😴','Rest soon · energy '+n.energy+'%']);if(dailyReady())list.push(['🎁','Daily reward ready']);if(state.money<50)list.push(['💴','Low on money · make money']);if(state.job&&state.lastShift!==state.day&&state.day>=(state.jobStart||1))list.push(['💼','Shift available today']);const s=state.story;if(state.student&&s&&s.phase!=='complete')list.push(['🎓','Next: '+window.ChinaLifeStudentStory.arrival[s.index].title]);const days=(7-state.day%7)%7||7,rent=rentDue();if(rent)list.push(['🏠','Rent ¥'+rent+' in '+days+' day'+(days>1?'s':'')]);const h=huntSummary();if(h.found<h.total)list.push(['🧧',(h.total-h.found)+' envelopes left · reset in '+untilReset()]);if(!dailyReady())list.push(['⏰','Next daily reward in '+untilReset()]);return list}
function tasksScreen(){const list=todayTasks();screen('⏱ Today','Day '+state.day+' · '+timeText(),'<div class="today-list">'+list.map(([icon,text])=>'<div><span>'+icon+'</span><b>'+escapeHTML(text)+'</b></div>').join('')+'</div>'+action('todayEarn','💴 Make money','Jobs, gigs and the office'))
 ;$('todayEarn').onclick=()=>earnScreen()}
// Notifications: an in-game banner, plus a phone notification when the game is in the background
// and the player allowed it in Settings.
let reminded='';
function notify(text,open){let banner=$('gameNotification');if(!banner){banner=document.createElement('button');banner.id='gameNotification';banner.className='message-notification';document.body.append(banner)}banner.textContent=text;banner.hidden=false;banner.onclick=()=>{banner.hidden=true;open?.()};clearTimeout(notify.t);notify.t=setTimeout(()=>banner.hidden=true,8000);
 if(document.hidden&&'Notification' in window&&Notification.permission==='granted'){const show=()=>new Notification('ChinaLife',{body:text,icon:'icons/icon-192.png'});navigator.serviceWorker?.ready.then(r=>r.showNotification('ChinaLife',{body:text,icon:'icons/icon-192.png'})).catch(show)??show()}}
function reminders(){if(!state.created)return;const fest=festivalToday();if(fest&&reminded!=='fest'+today()){reminded='fest'+today();setTimeout(()=>notify(fest+' · red envelopes pay double today!',huntScreen),4000);return}if(dailyReady()&&reminded!==today()){reminded=today();setTimeout(()=>notify('🎁 Your daily reward is ready. Tap to claim.',rankScreen),2500)}}
setInterval(()=>{try{reminders()}catch{}},60000);
