 screen('🎉 '+escapeHTML(e.title),(venue?venue[3]+' '+escapeHTML(venue[1])+' · ':'')+'Ends in '+(left>=60?Math.floor(left/60)+'h ':'')+left%60+'m',(e.body?'<p>'+escapeHTML(e.body)+'</p>':'')+(e.joined?'<p><b>✓ You joined this event.</b></p>':here?action('eventJoin','🎉 Join event'+(e.reward?' · +¥'+e.reward.toLocaleString():''),'Once per player'):action('eventGo','Go to '+escapeHTML(venue[1]),'Join when you arrive'))+(e.link?'<a class="soft-btn" href="'+escapeHTML(e.link)+'" target="_blank" rel="noopener noreferrer">More info</a>':''));
