   $('adminEvent').onsubmit=async ev=>{ev.preventDefault();try{await cloud.admin('create_event',{title:$('evTitle').value.trim(),body:$('evBody').value.trim(),place:$('evPlace').value,reward:Number($('evReward').value)||0,hours:Number($('evHours').value)||24,link:$('evLink').value.trim(),billboard:$('evBillboard').checked});toast('Event is live.');await cloud.refreshEvents();adminScreen('events')}catch(e){toast(e.message)}};
