function clubOpen(id){const h=clubHours[id];if(!h)return true;const hour=Math.floor(state.hour/60)%24;return hour>=h[0]||hour<h[1]}
// Real menus at food venues: each dish costs money and restores hunger (and sometimes energy or fun).
