for(const r of cityContent.restaurants)menus[r.id]=r.menu;for(const p of guangzhou.places)if(p.menu)menus[p.id]=p.menu;
function menuScreen(id){const p=L.find(x=>x[0]===id),items=menus[id];if(!items)return;screen('🍽 '+escapeHTML(p[1]),'Order something · paid on arrival',items.map(([name,price],i)=>action('menu-'+i,name+' · ¥'+price,'')).join(''));items.forEach(([name,price,hunger,fun,energy],i)=>$('menu-'+i).onclick=()=>{if(state.place!==id)return toast('Travel to '+p[1]+' first.');if(state.money<price)return earnScreen('You need ¥'+price+' for '+name.slice(2)+'.');state.money-=price;state.needs.hunger=Math.min(100,state.needs.hunger+hunger);state.needs.fun=Math.min(100,state.needs.fun+(fun||0));state.needs.energy=Math.min(100,state.needs.energy+(energy||0));advance(25);state.xp+=3;finish(name+' · delicious.');menuScreen(id)})}
// Certificates: reaching skill levels earns a certificate and a one-off reward.
function checkCertificates(){if(!state.created)return;state.certs=state.certs||[];for(const [id,name,skill,levelNeeded,reward] of certificates){if(state.certs.includes(id)||(state.skills[skill]||1)<levelNeeded)continue;state.certs.push(id);state.money+=reward;state.logs.unshift('Certificate earned: '+name+' · +¥'+reward);save();setTimeout(()=>notify('🎓 Certificate earned: '+name+' · +¥'+reward.toLocaleString(),skillsScreen),2000)}}
// Food delivery: order dishes from Shenyang's food places to wherever you are, with a small fee.
const deliveryFee=8;
function deliveryScreen(fainted){const shops=['market','african','cafe'].filter(id=>menus[id]&&L.some(p=>p[0]===id)),items=shops.flatMap(id=>menus[id].map(m=>[id,...m])).filter(m=>m[3]>=15);
 screen('🛵 Food delivery',(fainted?'Order something to eat · ':'')+'Delivered to you in 30 minutes · ¥'+deliveryFee+' delivery',items.map(([id,name,price,hunger],i)=>action('deliver-'+i,name+' · ¥'+(price+deliveryFee),escapeHTML(L.find(p=>p[0]===id)[1])+' · +'+hunger+' hunger')).join(''));
 items.forEach(([id,name,price,hunger,fun,energy],i)=>$('deliver-'+i).onclick=()=>{const total=price+deliveryFee;if(state.money<total)return earnScreen('You need ¥'+total+' for '+name.slice(2)+'.');state.money-=total;advance(30);state.needs.hunger=Math.min(100,state.needs.hunger+hunger);state.needs.fun=Math.min(100,state.needs.fun+(fun||0));state.needs.energy=Math.min(100,state.needs.energy+(energy||0));state.xp+=3;finish('🛵 Your '+name.slice(2).trim()+' arrived. Delicious.')})}
function rankUp(){if(!state.created)return;const i=rankIndex(state.xp);if(i<=(state.rankClaimed||0))return;const from=state.rankClaimed||0;state.rankClaimed=i;let total=0;for(let n=from+1;n<=i;n++)total+=rankReward(n);state.money+=total;const msg='Rank up! You are now '+ranks[i][2]+' '+ranks[i][1]+' · +¥'+total.toLocaleString();state.logs.unshift(msg);save();setTimeout(()=>notify(msg,rankScreen),1200)}
function claimDaily(){if(!dailyReady())return toast('Come back tomorrow for your next daily reward.');const streak=dailyStreak(),xp=20*streak,money=50*streak;state.streak=streak;state.lastVisit=today();state.xp+=xp;state.money+=money;finish('Daily reward · day '+streak+' streak · +'+xp+' XP · +¥'+money)}
async function rankScreen(){const i=rankIndex(state.xp),next=ranks[i+1],r=ranks[i];
 screen(r[2]+' '+r[1],next?(next[0]-state.xp).toLocaleString()+' XP to '+next[2]+' '+next[1]:'You reached the top rank.',
  '<progress class="rank-progress" max="'+(next?next[0]-r[0]:1)+'" value="'+(next?state.xp-r[0]:1)+'"></progress><p class="fine-print">'+state.xp.toLocaleString()+' XP · earn XP from activities, courses, shifts, story tasks and trips.</p>'
  +action('rankDaily',dailyReady()?'🎁 Claim daily reward':'✓ Daily reward claimed',dailyReady()?'Day '+dailyStreak()+' streak · +'+20*dailyStreak()+' XP · +¥'+50*dailyStreak():'Streak: '+(state.streak||0)+' day'+((state.streak||0)===1?'':'s')+' · come back tomorrow')
  +'<h3>Rank rewards</h3><div class="rank-list">'+ranks.map((x,n)=>'<div class="'+(n<=i?'reached':'')+'"><span>'+x[2]+'</span><b>'+x[1]+'</b><small>'+x[0].toLocaleString()+' XP'+(n?' · ¥'+rankReward(n).toLocaleString():'')+'</small></div>').join('')+'</div>'
  +(window.ChinaLifeCloud?.online?'<p class="fine-print">🟢 '+window.ChinaLifeCloud.online.online.toLocaleString()+' playing now · '+window.ChinaLifeCloud.online.players.toLocaleString()+' players in ChinaLife</p>':'')+'<h3>Top players</h3><ol id="leaderboard" class="leaderboard"><li>'+(window.ChinaLifeCloud?.signedIn?'Loading…':'Sign in with Hafrik to see the leaderboard.')+'</li></ol>');
 $('rankDaily').onclick=()=>{claimDaily();rankScreen()};
 if(!window.ChinaLifeCloud?.signedIn)return;
 try{const result=await window.ChinaLifeAuth.request('/chinalife/leaderboard.php','GET'),data=result.data||result;if(!$('leaderboard'))return;$('leaderboard').innerHTML=(data.players||[]).map(p=>'<li class="'+(p.own?'own':'')+'"><span>'+ranks[rankIndex(+p.xp)][2]+'</span><b>'+escapeHTML(p.name)+'</b><small>'+(+p.xp).toLocaleString()+' XP</small></li>').join('')+(data.position&&data.position>(data.players||[]).length?'<li class="own"><span>#'+data.position+'</span><b>You</b><small>'+state.xp.toLocaleString()+' XP</small></li>':'')}catch(e){if($('leaderboard'))$('leaderboard').innerHTML='<li>'+escapeHTML(e.message)+'</li>'}
}
