function studentProfile(start){const school=window.ChinaLifeStudentStory.universities.find(s=>s[0]===onboard.campus)||window.ChinaLifeStudentStory.universities[0];return {start,path:'study',country:start==='outside'?'Nigeria':'China',departure:start==='outside'?'Lagos':'Shenyang',studyCity:'Shenyang',university:school[1],studyLevel:'Undergraduate',major:'',campus:school[0],temporary:false}}
function next(){
 if(step===0&&!onboard.start)return toast('Choose where your ChinaLife begins.');
 if(accountName)onboard.name=accountName;
 const attaching=studentSetupMode==='attach';
 if(attaching){
  // An older Student character opting into the student story: keep all progress.
  state=JSON.parse(JSON.stringify(state));state.student=studentProfile(onboard.start);state.story={version:1,phase:'arrival',index:onboard.start==='outside'?0:1,season:'winter'};state.logs.unshift('Your student story begins.');studentSetupMode='create';save();$('onboarding').close();render();studentStory();return;
 }
 if(step===1&&!roles[onboard.role])return toast('Choose your role.');
 if(step===2&&!accountName&&(!onboard.name.trim()||onboard.name.trim().length>22))return toast('Choose a name with 1–22 characters.');
 if(step<2){step++;onboarding();return}
 const role=roles[onboard.role];
 state={...JSON.parse(JSON.stringify(blank)),created:true,name:onboard.name.trim(),color:onboard.color,appearance:{skin:onboard.skin||'#8b5c43',hair:onboard.hair||'cropped',trousers:'#28394b'},background:onboard.role,gender:onboard.gender||null,money:role.money};
 state.skills[role.skill]=2;state.city='Shenyang';
 if(onboard.role==='Student'){state.student=studentProfile(onboard.start);state.story={version:1,phase:'arrival',index:onboard.start==='outside'?0:1,season:'winter'};state.place=onboard.start==='outside'?'airport':state.student.campus}
 else state.place=onboard.start==='outside'?'airport':role.home;
 selected=state.place;state.visited=[state.place];state.logs=[onboard.start==='outside'?'You landed in Shenyang as a '+role.label.toLowerCase()+'.':'Your '+role.label.toLowerCase()+' life in Shenyang begins.'];
 studentSetupMode='create';save();$('onboarding').close();render();toast('Welcome to ChinaLife, '+state.name+'! Open your phone to see your goals.');
}

function studentStory(){
 if(!state.student){screen('Your student story','Season 0 · Student Life', '<p>Add your student profile and begin the Shenyang introduction. Your money, skills, friendships and existing progress are kept.</p>'+(state.background==='Student'?action('startStudentIntro','Add your student profile','Choose where you start and get your campus tasks'):'<p>Your '+escapeHTML(state.background)+' story is coming soon.</p>'));if($('startStudentIntro'))$('startStudentIntro').onclick=()=>{$('activityDialog').close();studentSetupMode='attach';step=0;onboard={name:state.name,color:state.color,start:'inside'};$('onboarding').showModal();onboarding()};return}
 const storyState=state,p=state.student,s=state.story,school=escapeHTML(p.university),temporary=p.temporary;
 const profile='<div class="student-profile"><b>'+school+'</b><span>'+escapeHTML(p.studyCity)+' · Student</span>'+(temporary?'<p>Your requested city or university is coming soon. Play at the temporary Shenyang campus while keeping your actual university in your profile.</p>':'')+'</div>';
 const login=!window.ChinaLifeCloud?.signedIn?'<button id="storySaveAccount" class="soft-btn">Save with Hafrik across devices</button>':'';
 if(s.phase==='complete'){screen('Your arrival introduction is complete','Your student life continues.',profile+'<p>Your room is ready, you have attended your first class and met the student community. Explore classes, clubs, food and friendships at your own pace.</p>'+action('storyCampus','Go to your playable campus',temporary?'Temporary Shenyang campus':p.university)+login);$('storyCampus').onclick=()=>{$('activityDialog').close();select(p.campus)};if($('storySaveAccount'))$('storySaveAccount').onclick=()=>{$('activityDialog').close();window.ChinaLifeCloud?.open()};return}
 const steps=window.ChinaLifeStudentStory.arrival,chapter=steps[s.index],venue=chapter.place==='campus'?p.campus:chapter.place,here=state.city==='Shenyang'&&state.place===venue;
 screen(chapter.title,'Student tasks · Shenyang · Winter',profile+'<p class="story-progress">Task '+(s.index+1)+' of '+steps.length+'</p><progress max="'+steps.length+'" value="'+s.index+'"></progress><p>'+escapeHTML(chapter.text)+'</p>'+action('storyNext',here?chapter.button:'Travel to '+(L.find(v=>v[0]===venue)?.[1]||'your venue'),here?'Continue your student story':'Complete this task at its venue')+login);
 $('storyNext').onclick=()=>{
  if(state!==storyState||state.story.phase!==s.phase||state.story.index!==s.index)return;
  if(!here){$('activityDialog').close();if(state.city!=='Shenyang'){toast('Return to Shenyang to continue your first-week story.');tripScreen();return}select(venue);return}
  if(!runningCallback&&window.ChinaLifeWorld)return sceneAction({kind:chapter.hunger?'eat':chapter.study?'study':'talk',x:0,z:2,label:chapter.title},$('storyNext').onclick);
  if(chapter.hunger)state.needs.hunger=Math.min(100,state.needs.hunger+chapter.hunger);if(chapter.social)state.needs.social=Math.min(100,state.needs.social+chapter.social);if(chapter.study)gain('Study',chapter.study);advance(chapter.minutes||30);state.xp+=10;state.logs.unshift(chapter.title+' completed.');
  // Replace the chapter object so a delayed duplicate callback cannot advance twice.
  const index=s.index+1;state.story=index<steps.length?{...s,index}:{version:1,phase:'complete',index:0,season:'winter'};
  save();render();studentStory();
 };
 if($('storySaveAccount'))$('storySaveAccount').onclick=()=>{$('activityDialog').close();window.ChinaLifeCloud?.open()};
}

