function validateSave(v){const bad=(field='character data')=>{throw new Error('Your saved character could not be loaded ('+field+'). Your account save has not been replaced.')};if(!v||v.created!==true)bad('character status');if(typeof v.name!=='string'||!v.name.trim()||v.name.length>64)bad('character name');if(!['Student','Worker','Creator','Entrepreneur','Tourist'].includes(v.background))bad('background');if(!L.some(p=>p[0]===v.place))bad('current venue');const num=(value,min,max,field='numeric progress')=>{if(typeof value==='string'&&/^-?\d+(\.\d+)?$/.test(value))value=Number(value);if(!Number.isFinite(value))bad(field);return Math.min(max,Math.max(min,value))};const list=(value,allowed)=>Array.isArray(value)?[...new Set(value.filter(x=>allowed.includes(x)))].slice(0,100):[];const r=JSON.parse(JSON.stringify(blank));r.created=true;r.name=v.name.trim();r.background=v.background;r.gender=['male','female'].includes(v.gender)?v.gender:null;r.ownedHomes=list(v.ownedHomes||[],cityContent.estates.map(h=>h.id));r.activeHome=r.ownedHomes.includes(v.activeHome)?v.activeHome:null;r.place=v.place;r.city=v.city??'Shenyang';if(!Object.keys(cityData).includes(r.city))bad('current city');r.day=num(v.day,1,36500,'day');r.hour=num(v.hour,0,1439,'hour');r.day=Math.round(r.day);r.hour=Math.round(r.hour);r.money=num(v.money,-10000000,1000000000,'money');r.transferTotal=num(v.transferTotal??0,-1000000000,1000000000);r.sharedXP=num(v.sharedXP??0,0,10000000,'shared activity XP');r.xp=num(v.xp,0,10000000,'xp');r.color=/^#[0-9a-f]{6}$/i.test(v.color)?v.color:'#18776d';v={...v,needs:v.needs||{},skills:v.skills||{}};for(const k of needs)r.needs[k]=num(v.needs[k]??60,0,100,k+' need');r.skills={};r.skillXP={};for(const k of ['Chinese','Social','Digital','Creativity','Fitness','Study','Network','Cooking','Music']){r.skills[k]=num(v.skills[k]??1,1,99);r.skillXP[k]=num(v.skillXP?.[k]??0,0,99)}r.trait=list(v.trait||[],traits,'personality traits');r.dream=['','0','1','2','3'].includes(v.dream)?v.dream:'';r.visited=list(v.visited,L.map(p=>p[0]),'visited venues');r.upgrades=list(v.upgrades||[],catalog.furniture.map(f=>f.id),'furniture inventory');r.properties={};for(const [city,type] of Object.entries(v.properties||{})){if(!Object.keys(cityData).includes(city)||!catalog.properties.some(p=>p.id===type))continue;r.properties[city]=type}r.propertyPortfolio={};for(const city of Object.keys(cityData)){const owned=list(v.propertyPortfolio?.[city]||[],catalog.properties.map(p=>p.id));if(r.properties[city]&&!owned.includes(r.properties[city]))owned.push(r.properties[city]);if(owned.length)r.propertyPortfolio[city]=owned}r.furnitureColors={};for(const [id,color] of Object.entries(v.furnitureColors||{})){if(!catalog.furniture.some(f=>f.id===id)||!/^#[0-9a-f]{6}$/i.test(color))continue;r.furnitureColors[id]=color}r.flightBookings=(Array.isArray(v.flightBookings)?v.flightBookings:[]).filter(f=>!(!f||typeof f.id!=='string'||!/^[a-z0-9-]{1,40}$/.test(f.id)||!Object.keys(cityData).includes(f.from)||!Object.keys(cityData).includes(f.to)||f.from===f.to||!['booked','flown','cancelled'].includes(f.status))).slice(-20).map(f=>{try{return {id:f.id,from:f.from,to:f.to,status:f.status,fare:num(f.fare,1,10000),hours:num(f.hours,1,12),day:num(f.day,1,36500)}}catch{return null}}).filter(Boolean);r.trips=list(v.trips||[],['Harbin','Beijing','Shanghai','Guangzhou','Shenzhen','Chengdu']);r.claimed=list(v.claimed||[],['explorer','routine','payday','language','friend','home','founder']);r.logs=Array.isArray(v.logs)?v.logs.filter(x=>typeof x==='string').slice(0,40).map(x=>x.slice(0,500)):[];r.job=['cafe-job','teacher','content','designer','sales','coach','delivery','translator'].includes(v.job)?v.job:null;r.jobStart=num(v.jobStart??1,1,36500);r.lastShift=num(v.lastShift??0,0,36500);r.shifts=num(v.shifts??0,0,100000);r.promotion=num(v.promotion??1,1,5);r.stats={activities:num(v.stats?.activities??0,0,1000000),shifts:num(v.stats?.shifts??r.shifts,0,1000000),businessOrders:num(v.stats?.businessOrders??0,0,1000000)};r.friends={};r.friendDay={};for(const id of ['mei','tunde','amina','leo']){r.friends[id]=num(v.friends?.[id]??0,0,100);r.friendDay[id]=num(v.friendDay?.[id]??0,0,36500)}r.eventHistory={};for(const k of Object.keys(v.eventHistory||{})){if(!/^[0-9]+$/.test(k)||+k<1||+k>36500||![0,1].includes(v.eventHistory[k]))continue;r.eventHistory[k]=v.eventHistory[k]}r.business=v.business?{level:num(v.business.level,1,3),orders:num(v.business.orders,0,100000),revenue:num(v.business.revenue,0,1000000000),lastOrder:num(v.business.lastOrder,0,36500)}:null;r.paidActivities={};for(const key of ['cafe:1'])r.paidActivities[key]=num(v.paidActivities?.[key]??0,0,36500);r.pantryDay=num(v.pantryDay??0,0,36500);r.dreamClaimed=v.dreamClaimed===true;r.reduceMotion=v.reduceMotion===true;r.rankClaimed=Math.min(ranks.length-1,Math.max(0,Number.isInteger(v.rankClaimed)?v.rankClaimed:rankIndex(r.xp)));r.lastVisit=/^\d{4}-\d{2}-\d{2}$/.test(v.lastVisit||'')?v.lastVisit:'';r.streak=Number.isInteger(v.streak)?Math.min(7,Math.max(0,v.streak)):0;r.treasures=v.treasures&&/^\d{4}-\d{2}-\d{2}$/.test(v.treasures.day||'')&&Array.isArray(v.treasures.found)?{day:v.treasures.day,found:v.treasures.found.filter(id=>L.some(p=>p[0]===id)).slice(0,10)}:null;r.treasureTotal=Number.isInteger(v.treasureTotal)?Math.max(0,Math.min(100000,v.treasureTotal)):0;r.foodHelpDay=Number.isInteger(v.foodHelpDay)?v.foodHelpDay:0;r.certs=Array.isArray(v.certs)?v.certs.filter(id=>certificates.some(c=>c[0]===id)):[];r.dice=Number.isInteger(v.dice?.day)&&Number.isInteger(v.dice?.count)?{day:v.dice.day,count:Math.max(0,Math.min(10,v.dice.count))}:null;r.gigs={};for(const [id] of gigs)if(Number.isInteger(v.gigs?.[id]))r.gigs[id]=v.gigs[id];r.secrets=Array.isArray(v.secrets)?v.secrets.filter(id=>secrets.some(s=>s[0]===id)):[];if(v.student){const p=v.student;if(!['inside','outside'].includes(p.start)||![...universityIds,'dongbei'].includes(p.campus))bad('student origin or campus');for(const key of ['country','departure','studyCity','university'])if(typeof p[key]!=='string'||!p[key].trim()||p[key].length>100)bad('student '+key);if(!window.ChinaLifeStudentStory.studyLevels.includes(p.studyLevel||'Undergraduate')||typeof (p.major??'')!=='string'||(p.major||'').length>100)bad('study level or major');r.student={start:p.start,path:'study',studyLevel:p.studyLevel||'Undergraduate',major:p.major||'',country:p.country,departure:p.departure,studyCity:p.studyCity,university:p.university,campus:p.campus,temporary:p.temporary===true};const story=v.story;if(!story||!['preparation','arrival','complete'].includes(story.phase)||(story.version!==undefined&&story.version!==1)||!Number.isInteger(story.index)||story.index<0||story.index>=(story.phase==='preparation'?window.ChinaLifeStudentStory.preparation.length:story.phase==='arrival'?window.ChinaLifeStudentStory.arrival.length:1))bad('student story progress');r.story=story.phase==='preparation'?{version:1,phase:'arrival',index:0,season:'winter'}:{version:1,phase:story.phase,index:story.index,season:'winter'}}r.appearance={skin:/^#[0-9a-f]{6}$/i.test(v.appearance?.skin)?v.appearance.skin:'#8b5c43',hair:['cropped','bun','cap'].includes(v.appearance?.hair)?v.appearance.hair:'cropped',trousers:'#28394b'};return r}
function escapeHTML(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function ensure(){if(!isOpen(state.city)){state.city='Shenyang';state.place='home';selected='home'}if(state.created&&!inCity(state.place)){state.place='home';selected='home'}state.ownedHomes=state.ownedHomes||[];state.activeHome=state.ownedHomes.includes(state.activeHome)?state.activeHome:null;state.properties=state.properties||{};state.propertyPortfolio=state.propertyPortfolio||{};for(const [city,type] of Object.entries(state.properties)){state.propertyPortfolio[city]=state.propertyPortfolio[city]||[];if(!state.propertyPortfolio[city].includes(type))state.propertyPortfolio[city].push(type)}state.furnitureColors=state.furnitureColors||{};state.flightBookings=state.flightBookings||[];state.city=state.city||'Shenyang';applyCity();state.paidActivities=state.paidActivities||{};state.appearance=state.appearance||{skin:'#8b5c43',hair:'cropped',trousers:'#28394b'};state.claimed=state.claimed||[];state.eventHistory=state.eventHistory||{};state.stats=state.stats||{activities:0,shifts:state.shifts||0,businessOrders:0};state.business=state.business||null;state.skillXP=state.skillXP||{};state.friends=state.friends||{};state.upgrades=state.upgrades||[];state.trips=state.trips||[];state.skills.Study=state.skills.Study||1;state.skills.Network=state.skills.Network||1;state.promotion=state.promotion||1;state.shifts=state.shifts||0}
function gain(skill,amount){ensure();state.skills[skill]=state.skills[skill]||1;state.skillXP[skill]=(state.skillXP[skill]||0)+amount;while(state.skillXP[skill]>=100){state.skillXP[skill]-=100;state.skills[skill]++;toast(skill+' reached level '+state.skills[skill])}}
let runningCallback=false;function sceneAction(spec,fn){return window.ChinaLifeWorld.perform({...spec,place:state.place},()=>{runningCallback=true;try{fn()}finally{runningCallback=false}})}
function screen(title,intro,body){$('activityDialog').classList.remove('travel-sheet');$('activityContent').innerHTML='<div class="activity-panel"><span class="eyebrow">YOUR LIFE IN CHINA</span><h2>'+title+'</h2><p class="lead">'+intro+'</p>'+body+'</div>';if(!$('activityDialog').open)$('activityDialog').showModal()}
function action(id,title,sub){return '<button class="choice-action" id="'+id+'"><b>'+title+'</b><span>'+sub+'</span></button>'}
function finish(msg){state.logs.unshift(msg);state.logs=state.logs.slice(0,40);save();render();toast(msg)}
function shiftBlocked(){if(state.day<(state.jobStart||1))return 'Your job starts tomorrow. Rest or train today.';if(state.lastShift===state.day)return 'You have already worked today. Come back next game day.';if(state.needs.energy<35||state.needs.hunger<25)return 'Eat and rest before your shift. You need at least 35 energy and 25 hunger.';return ''}
function shiftFeedback(message){const status=$('shiftStatus');if(status&&$('activityDialog').open)status.textContent=message;else toast(message)}
function workShift(style){const j=jobs.find(x=>x[0]===state.job);if(!j)return jobsDialog();const workplace=L.find(p=>p[1]===j[2]);if(state.place!==workplace[0])return toast('Travel to '+j[2]+' for your shift.');const blocked=shiftBlocked();if(blocked)return shiftFeedback(blocked);if(!runningCallback&&window.ChinaLifeWorld)return sceneAction({kind:state.place==='cafe'?'serve':state.place==='gym'?'exercise':'type',x:0,z:state.place==='cafe'?-1.8:0,label:'Working your shift'},()=>workShift(style));const pay=Math.round(j[4]*(1+(state.promotion-1)*.15)*(style==='focus'?1.15:1));state.lastShift=state.day;state.money+=pay;state.shifts++;state.stats.shifts++;state.needs.energy=Math.max(0,state.needs.energy-(style==='focus'?38:26));state.needs.hunger=Math.max(0,state.needs.hunger-20);advance(j[5]*60);gain(j[3],style==='focus'?35:25);state.xp+=25;if(state.shifts%3===0&&state.promotion<5)state.promotion++;$('activityDialog').close();finish('Shift complete: earned ¥'+pay+'. Career level '+state.promotion+'/5.')}
function shiftScreen(){const j=jobs.find(x=>x[0]===state.job);if(!j)return jobsDialog();const workplace=L.find(p=>p[1]===j[2]);if(state.place!==workplace[0]){screen(j[1],'Your shift takes place at '+j[2]+'.',action('goWork','Travel to work',j[2]));$('goWork').onclick=()=>{$('activityDialog').close();select(workplace[0])};return}screen(j[1],'Career level '+state.promotion+'/5 · '+state.shifts+' shifts completed. One shift per game day.','<p id="shiftStatus" class="journal-item" role="status" aria-live="polite">'+(shiftBlocked()||'Ready to work. Choose a shift to begin.')+'</p>'+action('steadyShift','Steady shift','Balanced pace · '+j[5]+' hours · uses 26 energy')+action('focusShift','Focused shift','15% extra pay · '+j[5]+' hours · uses 38 energy'));$('steadyShift').onclick=()=>workShift('steady');$('focusShift').onclick=()=>workShift('focus')}
// Learn: every skill with its level and the places that teach it (any activity that says "trains <skill>").
const allSkills=['Chinese','Study','Digital','Creativity','Cooking','Music','Fitness','Social','Network'],skillIcons={Chinese:'🀄',Study:'📖',Digital:'💻',Creativity:'🎨',Cooking:'🥟',Music:'🎧',Fitness:'💪',Social:'💬',Network:'🤝'};
function skillsScreen(){const teach=skill=>L.filter(p=>inCity(p[0])&&p[7].some(a=>a[1].includes('trains '+skill)));screen('Learn','Take courses and practise at places across Shenyang. Every 100 points raises a skill level and unlocks new jobs.','<h3>Certificates</h3><div class="rank-list">'+certificates.map(([id,name,skill,lv,reward])=>{const has=(state.certs||[]).includes(id);return '<div class="'+(has?'reached':'')+'"><span>'+(has?'🎓':'📜')+'</span><b>'+name+'</b><small>'+skill+' level '+lv+' · ¥'+reward.toLocaleString()+'</small></div>'}).join('')+'</div><h3>Skills</h3>'+allSkills.map(k=>'<div class="skill-item"><b>'+skillIcons[k]+' '+k+' · Level '+(state.skills[k]||1)+'</b><progress max="100" value="'+(state.skillXP[k]||0)+'"></progress><span>'+(state.skillXP[k]||0)+'/100 to next level</span><div class="learn-places">'+teach(k).map(p=>'<button data-learn="'+p[0]+'">'+p[3]+' '+escapeHTML(p[1])+'</button>').join('')+'</div></div>').join(''));$('activityContent').querySelectorAll('[data-learn]').forEach(b=>b.onclick=()=>{$('activityDialog').close();select(b.dataset.learn)})}
const contacts=[['mei','Mei','campus','Student · enjoys language exchanges'],['tunde','Tunde','business','Founder · building a small studio'],['amina','Amina','ef','New arrival · looking for a study partner'],['leo','Leo','gym','Trainer · always ready for basketball']];
function peopleScreen(){screen('People in your city','Four simulated characters, each with a story. Visit their usual spot to talk.',contacts.map(c=>action('friend-'+c[0],c[1]+' · '+((state.friends[c[0]]||0)>=60?'Close friend':(state.friends[c[0]]||0)>=30?'Friend':'Acquaintance'),c[3]+' · Bond '+(state.friends[c[0]]||0)+'/100')).join(''));contacts.forEach(c=>$('friend-'+c[0]).onclick=()=>personScreen(c[0]))}
const dialogue={mei:{intro:'I came here to study engineering. At first, I was too nervous to speak in class. Language exchanges helped.',skill:'Chinese',answers:['Let’s practise a phrase together. Getting it wrong is part of learning.','The EFH language class is a good place to start. A little practice each day adds up.','I miss home too sometimes. Sharing the small wins makes this city feel less lonely.']},tunde:{intro:'I’m building a creative studio. Finding my first client was harder than setting up the business.',skill:'Network',answers:['Tell me what you are working on. There might be someone I can introduce you to.','Train your Digital and Network skills before opening a studio. Start small and deliver consistently.','That reminds me of my first week here. Nothing went to plan, but I met people who helped.']},amina:{intro:'I’ve just arrived. I’m still figuring out the buses, the food, and where to find people to study with.',skill:'Study',answers:['Want to study together sometime? It helps to have someone to compare notes with.','Try a campus lecture and join the international club. That is how I started finding my way.','Thank you for sharing that. It makes starting over feel a little less frightening.']},leo:{intro:'Training keeps me grounded. You don’t have to be good at basketball to join us.',skill:'Fitness',answers:['Come back for a workout. Consistency matters more than a perfect first session.','Keep your energy and hunger balanced before training. A walk in Nanhu Park also helps.','We all have those days. The next game is a fresh start.']}};
function talkNPC(id,topic){const c=contacts.find(c=>c[0]===id);if(!c||!Number.isInteger(topic)||topic<0||topic>2)return false;if(state.place!==c[2])return false;if(state.friendDay?.[id]===state.day){toast('Catch up with '+c[1]+' again tomorrow.');return false}if(!runningCallback&&window.ChinaLifeWorld){sceneAction({kind:'talk',x:-2+contacts.filter(p=>p[2]===c[2]).findIndex(p=>p[0]===id)*2,z:2.1,label:'Catch up with '+c[1]},()=>talkNPC(id,topic));return false}state.friendDay=state.friendDay||{};state.friendDay[id]=state.day;state.friends[id]=Math.min(100,(state.friends[id]||0)+15);state.needs.social=Math.min(100,state.needs.social+20);state.needs.fun=Math.min(100,state.needs.fun+5);gain(topic===1?dialogue[id].skill:'Social',20);advance(45);finish(c[1]+': '+dialogue[id].answers[topic]);return true}
function personScreen(id){const c=contacts.find(c=>c[0]===id);if(!c){const p=L.find(p=>p[0]===state.place);screen('Welcome to '+p[1],'Venue host · simulated character','<p>Make yourself comfortable. You can find today’s activities below.</p>'+p[7].map((a,i)=>action('hostAct'+i,a[0],a[1])).join(''));p[7].forEach((a,i)=>$('hostAct'+i).onclick=()=>activity(p,i));return}const d=dialogue[id],here=state.place===c[2],done=state.friendDay?.[id]===state.day;screen(c[1],c[3]+' · Bond '+(state.friends[id]||0)+'/100','<blockquote class="npc-quote">'+d.intro+'</blockquote>'+(state.friends[id]>=60?'<p>You are close friends. '+c[1]+' is glad to see you.</p>':'')+(here?['Ask about their day','Ask for local advice','Share a story from home'].map((t,i)=>action('topic'+i,done?'Talked today':t,'45 minutes · friendship and skill growth')).join(''):action('meetTravel','Go and meet '+c[1],L.find(p=>p[0]===c[2])[1])));if(here)[0,1,2].forEach(i=>{$('topic'+i).disabled=done;$('topic'+i).onclick=()=>{if(talkNPC(id,i))screen(c[1],'Bond '+state.friends[id]+'/100 · conversation complete','<blockquote class="npc-quote">'+d.answers[i]+'</blockquote>'+action('backPeople','Back to people','Catch up again tomorrow'));if($('backPeople'))$('backPeople').onclick=peopleScreen}});else $('meetTravel').onclick=()=>{$('activityDialog').close();select(c[2])}}

const transport=[['walkTravel',0,45,8,'Walk','walk'],['bikeTravel',2,25,4,'Shared bike','bike'],['metroTravel',4,20,2,'Metro','metro'],['busTravel',2,30,2,'Bus','bus'],['cabTravel',25,10,0,'Cab','cab'],['didiEconomyTravel',18,12,0,'DiDi Economy','didi-economy'],['didiPremiumTravel',38,8,0,'DiDi Premium','didi-premium']];
function travelScreen(id){const target=L.find(p=>p[0]===id);screen('Go to '+target[1],'Choose your ride. Game fares use virtual yuan.',transport.map(t=>action(t[0],t[4]+' · '+(t[1]?'¥'+t[1]:'free'),t[2]+' minutes · '+(t[3]?'uses '+t[3]+' energy':'no energy cost'))).join(''));$('activityDialog').classList.add('travel-sheet');transport.forEach(t=>$(t[0]).onclick=()=>{if(t[1]>0&&state.money<t[1])return earnScreen('Not enough money.');const slowHome=id==='home'&&t[1]===0&&state.needs.energy<t[3];if(state.needs.energy<t[3]&&!slowHome)return toast('Choose transport or rest first.');if(!runningCallback&&window.ChinaLifeWorld){const commit=$(t[0]).onclick;const mode=t[5];return window.ChinaLifeWorld.journey({from:state.place,to:id,mode,label:'To '+target[1]},()=>{runningCallback=true;try{commit()}finally{runningCallback=false}})}state.money-=t[1];state.needs.energy=Math.max(0,state.needs.energy-t[3]);advance(slowHome?90:t[2]);$('activityDialog').close();arrive(id);finish('Arrived at '+target[1]+'.')})}
function tripScreen(){const cities=Object.entries(cityData).map(([name,c],i)=>[name,c,i]).filter(([name])=>isOpen(name));screen('Choose your city','Travel changes your playable map. Fares and journey times are fictional game values. Your furnished apartment is available in every city.',action('openFlights','Book a flight','Visit the airport and choose your destination')+'<div class="city-picker">'+cities.map(([name,c,i])=>action('trip-'+i,c.han+' · '+name+(state.city===name?' · Here':isOpen(name)?'':' · Coming soon')+(window.ChinaLifeCloud?.online?' · '+(window.ChinaLifeCloud.online.cities[name]||0)+' online':''),isOpen(name)?c.tag+' · '+(state.city===name?'Explore this city':'¥'+c.fare+' · '+c.hours+'h'):'We are building '+name+'. Shenyang is open now.')).join('')+'</div><p class="map-note">These are game maps. Unnamed businesses, restaurants and churches are fictional venues.</p>');$('openFlights').onclick=airportScreen;cities.forEach(([name,c,i])=>$('trip-'+i).onclick=()=>{if(!isOpen(name))return toast(name+' is coming soon. Keep exploring Shenyang.');if(state.city===name){$('activityDialog').close();window.ChinaLifeWorld?.map();return}if(state.money<c.fare)return earnScreen('Not enough money to travel.');state.money-=c.fare;advance(c.hours*60);state.city=name;state.place='station';selected='station';applyCity();state.needs.fun=Math.min(100,state.needs.fun+20);if(name!=='Shenyang'&&!state.trips.includes(name)){state.trips.push(name);state.xp+=60}if(!state.visited.includes('station'))state.visited.push('station');$('activityDialog').close();finish('You arrived in '+name+'. Explore your new city.');window.ChinaLifeWorld?.map()})}
function hafrikScreen(){screen('Hafrik','Your community beyond the game.','<a class="primary-btn external-app" href="https://hafrik.com" target="_blank" rel="noopener noreferrer">Open Hafrik</a><p>Connect with foreigners in China, join Spaces and find community events. Your Hafrik account is separate from this prototype.</p>')}
function whatsappScreen(){screen('WhatsApp','Continue a conversation in your own WhatsApp app.','<p>Enter a number shared with you voluntarily, including its country code. ChinaLife does not read your contacts or WhatsApp messages.</p><form id="whatsappForm"><label for="whatsappNumber">Phone number</label><input id="whatsappNumber" type="tel" class="name-input" placeholder="+86 or +234…" autocomplete="off" maxlength="20"><button class="primary-btn" type="submit">Open WhatsApp chat</button></form><p>For conversations inside ChinaLife, use the Chat app.</p>'+action('openGameChat','Open ChinaLife Chat','Venue chat, friends and private conversations'));$('openGameChat').onclick=()=>window.ChinaLifeSocial?.open();$('whatsappForm').onsubmit=e=>{e.preventDefault();const number=$('whatsappNumber').value.replace(/[\s()+-]/g,'');if(!/^[1-9]\d{7,14}$/.test(number))return toast('Enter a valid number with its country code.');window.open('https://wa.me/'+number,'_blank','noopener,noreferrer')}}

function rentDue(){return state.properties?.[state.city]||(state.city==='Shenyang'&&state.ownedHomes?.length)?0:(state.background==='Student'?600:state.background==='Creator'?1200:2400)}
const furniture=[['bed','Comfortable bed',450,'Rest restores 15 extra energy'],['kitchen','Kitchen kit',280,'Home meals restore 10 extra hunger'],['desk','Study desk',650,'Train Digital at home']];
const homeInteriors={rental:{title:'Starter home',finish:'#a4b4b8',included:[],features:'A practical place to begin.'},apartment:{title:'City apartment',finish:'#598695',included:['rug','lamp'],features:'Soft lighting and a comfortable city living room.'},townhouse:{title:'Garden townhouse',finish:'#a87548',included:['rug','lamp','plant','dining'],features:'Warm wood, a dining room and a tree-lined garden.'},villa:{title:'Courtyard villa',finish:'#588878',included:['rug','lamp','plant','art','dining','tv'],features:'A furnished lounge, courtyard pool and private garden.'},penthouse:{title:'Skyline penthouse',finish:'#344b68',included:['rug','lamp','art','tv','dining','aquarium'],features:'Panoramic windows, marble finishes and a skyline terrace.'},mansion:{title:'Garden mansion',finish:'#a48243',included:['rug','lamp','plant','art','tv','dining','piano','aquarium'],features:'An elegant furnished lounge, piano, swimming pool and landscaped grounds.'}};
function chooseHome(){if(window.ChinaLifeWorld?.busy)return toast('Finish your current action first.');const options=(state.propertyPortfolio[state.city]||[]).map(type=>({id:'home',type,name:homeTiers().find(h=>h.id===type)?.name||type}));if(state.city==='Shenyang')for(const h of cityContent.estates)if(state.ownedHomes.includes(h.id))options.push({id:h.id,type:h.type,name:h.name});if(!options.length)options.push({id:'home',type:'rental',name:roleHome().start});screen('Which home in '+escapeHTML(state.city)+'?','Choose where you want to go. These are your homes in this city.',options.map((h,i)=>action('choose-home-'+i,escapeHTML(h.name),homeInteriors[h.type].features+(state.place===h.id&&homeType()===h.type?' · You are here':''))).join('')+action('homeBrowse','Browse homes','View available properties'));$('homeBrowse').onclick=homesScreen;options.forEach((h,i)=>$('choose-home-'+i).onclick=()=>{if(window.ChinaLifeWorld?.busy)return toast('Finish your current action first.');if(h.id==='home'){if(h.type!=='rental')state.properties[state.city]=h.type;state.activeHome=null}else state.activeHome=h.id;save();render();$('activityDialog').close();select(h.id)})}
function homeScreen(){if(!isResidence(state.place)){screen('Your apartment','Return home to rest, cook or manage your furniture.',action('goHome','Travel home','Choose how to get back'));$('goHome').onclick=()=>{$('activityDialog').close();select(homeAddress())};return}screen('Make yourself at home',''+(homeType()!=='rental'?'Owned '+homeType()+' · ':'Rented home · ')+'Weekly rent: ¥'+(rentDue())+'. Next due on day '+(state.day+(7-state.day%7))+'.',action('homeShop','Furniture & property shop','See the products, choose a finish and buy with virtual yuan')+action('homeRest','Sleep until morning','Move to 08:00 tomorrow · restore energy')+action('homeShower','Shower and freshen up','30 minutes · restore hygiene and bladder')+(state.money<18&&state.pantryDay!==state.day?action('pantryMeal','Use your emergency pantry','Free basic meal · once per day · restores hunger'):'')+furniture.map(f=>action('buy-'+f[0],f[1]+(state.upgrades.includes(f[0])?' · Owned':' · ¥'+f[2]),f[3])).join('')+(state.upgrades.includes('desk')?action('homeStudy',roleHome().desk[0],'2 hours ·'+roleHome().desk[2]+' · uses 12 energy'):''));$('homeShop').onclick=shopScreen;if($('pantryMeal'))$('pantryMeal').onclick=()=>{if(!runningCallback&&window.ChinaLifeWorld)return sceneAction({kind:'eat',x:1,z:3.2,label:'Have a pantry meal'},$('pantryMeal').onclick);if(state.pantryDay===state.day)return;state.pantryDay=state.day;state.needs.hunger=Math.min(100,state.needs.hunger+35);advance(30);finish('A basic pantry meal helped you get back on your feet.');homeScreen()};$('homeRest').onclick=()=>{if(!runningCallback&&window.ChinaLifeWorld)return sceneAction({kind:'sleep',x:-3,z:1,label:'Sleep until morning'},$('homeRest').onclick);advance(1440-state.hour+480);state.needs.energy=state.upgrades.includes('bed')?100:85;state.needs.hunger=Math.max(0,state.needs.hunger-10);arrive(state.place);finish('A new morning. Your next move is yours.');homeScreen()};$('homeShower').onclick=()=>{if(!runningCallback&&window.ChinaLifeWorld)return sceneAction({kind:'wash',x:4,z:3,label:'Freshen up'},$('homeShower').onclick);advance(30);state.needs.hygiene=100;state.needs.bladder=100;arrive(state.place);finish('Freshened up and ready.');homeScreen()};furniture.forEach(f=>$('buy-'+f[0]).onclick=()=>{if(state.upgrades.includes(f[0]))return toast('You already own this.');if(state.money<f[2])return earnScreen('Not enough money.');state.money-=f[2];state.upgrades.push(f[0]);finish('Your home now has a '+f[1].toLowerCase()+'.');homeScreen()});if($('homeStudy'))$('homeStudy').onclick=()=>{if(!runningCallback&&window.ChinaLifeWorld)return sceneAction({kind:'type',x:3,z:-0.8,label:roleHome().desk[0]},$('homeStudy').onclick);if(state.needs.energy<12)return toast('Rest first.');state.needs.energy-=12;advance(120);gain(roleHome().desk[1],25);finish('Two focused hours at your desk. '+roleHome().desk[1]+' improved.');homeScreen()}}
async function fortuneScreen(){screen('Hidden opportunities','Explore, train and build your studio. Major breakthroughs can fund your homes.', '<div id="fortuneBody">Loading opportunities…</div>');const cloud=window.ChinaLifeCloud;if(!cloud?.signedIn){$('fortuneBody').innerHTML=action('fortuneLogin','Save with Hafrik','Account connection is needed for large rewards');$('fortuneLogin').onclick=()=>{$('activityDialog').close();cloud?.open()};return}try{if(!await cloud.upload())throw Error('Save your character first.');const r=await window.ChinaLifeAuth.request('/chinalife/fortune.php','GET'),body=$('fortuneBody');if(!body)return;body.innerHTML=(r.data||r).opportunities.map(o=>'<article class="fortune-card"><h3>'+escapeHTML(o.title)+'</h3><p>'+escapeHTML(o.hint)+'</p>'+(o.reward?'<b>¥'+o.reward.toLocaleString()+'</b>':'<b>Reward undiscovered</b>')+action('fortune-'+o.id,o.claimed?'Claimed':o.ready?'Claim breakthrough reward':'Keep exploring & progressing',o.claimed?'Paid once to your account':o.ready?'One reward per account':'Build skills, complete activities and deliver studio orders')+'</article>').join('');for(const o of (r.data||r).opportunities){$('fortune-'+o.id).disabled=o.claimed||!o.ready;$('fortune-'+o.id).onclick=async()=>{$('fortune-'+o.id).disabled=true;try{const res=await window.ChinaLifeAuth.request('/chinalife/fortune.php','POST',{id:o.id});await cloud.syncTransfers();toast((res.data||res).duplicate?'Already claimed.':'Breakthrough earned: ¥'+o.reward.toLocaleString());fortuneScreen()}catch(e){toast(e.message);$('fortune-'+o.id).disabled=false}}}}catch(e){if($('fortuneBody'))$('fortuneBody').textContent=e.message}}
function estateScreen(id){const h=cityContent.estates.find(h=>h.id===id);if(!h)return;const owned=state.ownedHomes.includes(id);screen(h.name,'A personal '+h.type+' in the ChinaLife city.', '<p>¥'+h.price.toLocaleString()+' · '+(owned?'Owned':'Available to buy')+'</p>'+action('estateBuy',owned?'Use as your home':'Buy this home',owned?'Set this as your Home destination':'Purchase this city address')+action('estatePortfolio','Your homes','View every home you own'));$('estateBuy').onclick=()=>{if(window.ChinaLifeWorld?.busy)return toast('Finish your current action first.');if(!state.ownedHomes.includes(id)){if(state.money<h.price)return earnScreen('You need ¥'+(h.price-state.money).toLocaleString()+' more for this home.');state.money-=h.price;state.ownedHomes.push(id)}state.activeHome=id;if(state.city==='Shenyang'&&isResidence(state.place))arrive(id);finish('Your home is now '+h.name+'.');estateScreen(id)};$('estatePortfolio').onclick=homesScreen}
function homesScreen(){const estates=cityContent.estates;screen('Your homes','Own several addresses and choose where you live.',Object.entries(state.propertyPortfolio).flatMap(([city,types])=>types.map(type=>'<p class="journal-item">🏠 '+escapeHTML(city)+' · '+escapeHTML(catalog.properties.find(p=>p.id===type)?.name||type)+'</p>')).join('')+estates.map(h=>action('estate-'+h.id,escapeHTML(h.name)+(state.ownedHomes.includes(h.id)?' · Owned':''),h.type+' · ¥'+h.price.toLocaleString()+(state.activeHome===h.id?' · Your home':''))).join(''));for(const h of estates)$('estate-'+h.id).onclick=()=>{estateScreen(h.id);$('activityContent').insertAdjacentHTML('beforeend',action('estateVisit','Visit this address','Find it on the city map'));$('estateVisit').onclick=()=>{$('activityDialog').close();if(state.city!=='Shenyang')return toast('Travel to Shenyang to visit this home.');select(h.id)}}}
const isResidence=id=>id==='home'||(state.ownedHomes||[]).includes(id),homeAddress=()=>state.city==='Shenyang'&&(state.ownedHomes||[]).includes(state.activeHome)?state.activeHome:'home';
function homeType(id=state.place){const h=cityContent.estates.find(h=>h.id===id);return h?.type||state.properties?.[state.city]||'rental'}
let shopMode='furniture',shopItem='bed',shopColor='#16897b';
function shopScreen(mode=shopMode,id=shopItem){shopMode=mode;const items=mode==='properties'?homeTiers():catalog.furniture;shopItem=items.some(f=>f.id===id)?id:items[0].id;const item=items.find(f=>f.id===shopItem),owned=mode==='properties'?(state.propertyPortfolio[state.city]||[]).includes(item.id):state.upgrades.includes(item.id);shopColor=state.furnitureColors[item.id]||shopColor;screen('Make room for your life','Virtual furniture and personal game homes. Purchases are saved with your character.',action('shopHomes','My homes & city addresses','Browse your portfolio and homes around Shenyang')+action('shopFortune','Discover major opportunities','Earn larger rewards through progression')+'<div class="shop-tabs"><button id="shopFurniture" class="'+(mode==='furniture'?'active':'')+'">Furniture</button><button id="shopProperties" class="'+(mode==='properties'?'active':'')+'">Homes in '+state.city+'</button></div><div class="shop-preview"><div id="productPreview" aria-label="Three-dimensional product preview"></div><button id="rotateProduct">Rotate preview ↻</button></div><div class="shop-product"><div><h3>'+item.name+'</h3><p>'+item.detail+'</p></div><strong>¥'+item.price.toLocaleString()+'</strong></div>'+(mode==='furniture'?'<div class="finish-picker">'+[['#16897b','Teal'],['#426dba','Blue'],['#d6a362','Sand']].map(([c,name])=>'<button data-finish="'+c+'" class="'+(shopColor===c?'active':'')+'">'+name+'</button>').join('')+'</div>':'')+'<button id="shopBuy" class="primary-btn shop-buy">'+(owned?(mode==='furniture'?'Apply this finish':'Use this home'):'Buy '+item.name+' · ¥'+item.price.toLocaleString())+'</button><div class="shop-grid">'+items.map(f=>'<button class="shop-card '+(f.id===item.id?'selected':'')+'" data-item="'+f.id+'"><canvas data-product="'+f.id+'" width="240" height="160" aria-label="'+f.name+' preview"></canvas><b>'+f.name+'</b><span>¥'+f.price.toLocaleString()+(mode==='furniture'&&state.upgrades.includes(f.id)?' · Owned':'')+'</span></button>').join('')+'</div><p class="map-note">Furniture is installed in fixed room positions. Home ownership removes rent in this city. Each home type is purchased once. Switch between your owned home types for free.</p>');$('shopHomes').onclick=homesScreen;$('shopFortune').onclick=fortuneScreen;$('shopFurniture').onclick=()=>shopScreen('furniture','bed');$('shopProperties').onclick=()=>shopScreen('properties','apartment');$('activityContent').querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>shopScreen(mode,b.dataset.item));$('activityContent').querySelectorAll('[data-finish]').forEach(b=>b.onclick=()=>{shopColor=b.dataset.finish;previewShop();b.parentNode.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b))});$('rotateProduct').onclick=()=>window.ChinaLifePreview?.rotate();$('shopBuy').disabled=false;$('shopBuy').onclick=()=>{if(mode==='properties'&&window.ChinaLifeWorld?.busy)return toast('Finish your current action first.');if(mode==='furniture'){if(!state.upgrades.includes(item.id)){if(state.money<item.price)return earnScreen('Not enough money.');state.money-=item.price;state.upgrades.push(item.id)}state.furnitureColors[item.id]=shopColor;finish(item.name+' is ready in your home.')}else{if(!(state.propertyPortfolio[state.city]||[]).includes(item.id)){if(state.money<item.price)return earnScreen('Not enough money.');state.money-=item.price;(state.propertyPortfolio[state.city]||= []).push(item.id)}state.properties[state.city]=item.id;state.activeHome=null;if(isResidence(state.place))arrive('home');finish('You now own a '+item.name.toLowerCase()+' in '+state.city+'.')}shopScreen(mode,item.id)};previewShop()}
function previewShop(){window.dispatchEvent(new CustomEvent('chinalife:preview',{detail:{mode:shopMode,id:shopItem,color:shopColor}}))}
function flightQuote(from,to){const grid={Shenyang:[6,1],Harbin:[6,0],Beijing:[4,2],Shanghai:[6,4],Guangzhou:[3,6],Shenzhen:[4,6],Chengdu:[1,4]},a=grid[from],b=grid[to],distance=Math.hypot(a[0]-b[0],a[1]-b[1]);return {fare:Math.round((200+distance*140)/10)*10,hours:Math.max(2,Math.ceil(distance*.7))}}
function airportScreen(){if(state.place!=='airport'){screen('Flights from '+state.city,'Visit the airport to book, board or cancel a game flight.',action('goAirport','Travel to the airport',state.city+' Airport'));$('goAirport').onclick=()=>{$('activityDialog').close();select('airport')};return}const destinations=Object.entries(cityData).filter(([city])=>city!==state.city).map(([city,c],i)=>[city,c,i]).filter(([city])=>isOpen(city));screen(state.city+' Airport','Choose a destination. Booking charges virtual yuan; boarding completes the journey. These are game flights, not real airline bookings.','<h3>Your tickets</h3>'+state.flightBookings.filter(f=>f.status==='booked').map(f=>'<div class="boarding-pass"><b>'+f.from+' ✈ '+f.to+'</b><span>CL-'+f.id.toUpperCase()+' · ¥'+f.fare+' · '+f.hours+'h</span><button data-board="'+f.id+'">Board flight</button><button data-cancel="'+f.id+'">Cancel · 90% refund</button></div>').join('')+action('scenicFlight','Scenic flight over '+state.city+' · ¥180','1 hour · see the skyline from the air and land back here')+'<h3>Departures from '+state.city+'</h3>'+(!destinations.length?'<p>No other cities are open for flights yet.</p>':'')+destinations.map(([city,c,i])=>action('flight-'+i,city+(isOpen(city)?' · Economy':' · Coming soon'),isOpen(city)?'¥'+flightQuote(state.city,city).fare+' · '+flightQuote(state.city,city).hours+' hours in game':'Flights open when '+city+' launches')).join(''));$('scenicFlight').onclick=()=>{if(state.money<180)return toast('You need ¥180 for a scenic flight.');const flown=state,home=state.city;$('activityDialog').close();const landed=()=>{if(state!==flown)return;state.money-=180;advance(60);state.needs.fun=Math.min(100,state.needs.fun+30);state.xp+=15;finish('You flew over '+home+' and landed back at the airport.');checkSecrets('jet-setter');window.ChinaLifeWorld?.venue('airport')};if(window.ChinaLifeWorld?.flight)window.ChinaLifeWorld.flight({label:'Scenic flight over '+home,scenic:true},landed);else landed()};destinations.forEach(([city,c,i])=>$('flight-'+i).onclick=()=>{if(!isOpen(city))return toast(city+' is coming soon.');const fare=flightQuote(state.city,city).fare;if(state.money<fare)return earnScreen('Not enough money.');if(state.flightBookings.filter(f=>f.status==='booked').length>=3)return toast('You can hold three active tickets. Board or cancel one first.');state.money-=fare;state.flightBookings.push({id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),from:state.city,to:city,fare,hours:flightQuote(state.city,city).hours,day:state.day,status:'booked'});if(state.flightBookings.length>20)state.flightBookings=state.flightBookings.slice(-20);finish('Ticket booked: '+state.city+' to '+city+'.');airportScreen()});$('activityContent').querySelectorAll('[data-board]').forEach(b=>b.onclick=()=>{const f=state.flightBookings.find(f=>f.id===b.dataset.board);if(!f||f.status!=='booked')return;if(f.from!==state.city)return toast('This flight departs from '+f.from+'.');const flown=state;
 // The city changes mid-flight so the plane can be seen landing in the destination.
 const arrive=()=>{if(state!==flown||f.status!=='booked')return;f.status='flown';advance(f.hours*60);state.city=f.to;state.place='airport';selected='airport';applyCity();if(f.to!=='Shenyang'&&!state.trips.includes(f.to)){state.trips.push(f.to);state.xp+=60}if(!state.visited.includes('airport'))state.visited.push('airport');save()};
 const landed=()=>{if(state!==flown)return;arrive();finish('Landed in '+f.to+'. Welcome to your next chapter.');window.ChinaLifeWorld?.venue('airport')};
 $('activityDialog').close();if(window.ChinaLifeWorld?.flight)return window.ChinaLifeWorld.flight({label:'Flight to '+f.to,arrive},landed);landed()});$('activityContent').querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{const f=state.flightBookings.find(f=>f.id===b.dataset.cancel);if(!f||f.status!=='booked')return;f.status='cancelled';state.money+=Math.floor(f.fare*.9);finish('Flight cancelled. 90% of the virtual fare was refunded.');airportScreen()})}
function universityScreen(){screen('Your university','Choose your campus in the ChinaLife version of Shenyang.',cityContent.universities.map(s=>action('school-'+s.id,escapeHTML(s.name),s.district+' · '+s.focus+(state.student.campus===s.id?' · Your campus':''))).join(''));for(const school of cityContent.universities)$('school-'+school.id).onclick=()=>{state.student={...state.student,campus:school.id,university:school.name,studyCity:'Shenyang',temporary:false};save();render();profileScreen()}}
function profileScreen(){screen(escapeHTML(state.name||'New arrival'),'Level '+level()+' · '+roleOf().label+' · '+state.visited.length+' places explored', action('profileHomes','Your homes','View your property portfolio')+action('profileFortune','Hidden opportunities','Explore the path to major rewards')+action('profileStory','Your student story','Your starting point, university and current chapter')+(state.student?action('profileUniversity','Your university',state.student.university):'')+action('profileLook','Edit your appearance','Choose skin tone, hairstyle and outfit')+'<p><b>Your dream:</b> '+(dreams[+state.dream]?.[0]||'Find your direction')+'</p><p>'+state.trips.length+' cities visited · '+Object.values(state.friends).filter(v=>v>=60).length+' close friends · '+state.upgrades.length+' home upgrades</p><h3>Your journal</h3>'+state.logs.slice(0,10).map(l=>'<p class="journal-item">'+escapeHTML(l)+'</p>').join(''));if($('profileUniversity'))$('profileUniversity').onclick=universityScreen;$('profileLook').onclick=appearanceScreen;$('profileHomes').onclick=homesScreen;$('profileFortune').onclick=fortuneScreen;$('profileStory').onclick=studentStory}

const quests=[
{id:'explorer',title:'Find your feet',detail:'Visit five city venues',target:5,value:()=>state.visited.length,money:120,xp:30},
{id:'routine',title:'Build a routine',detail:'Complete ten location activities',target:10,value:()=>state.stats.activities,money:180,xp:50},
{id:'payday',title:'Earn your place',detail:'Finish three career shifts',target:3,value:()=>state.stats.shifts,money:250,xp:60},
{id:'language',title:'Speak with confidence',detail:'Reach Chinese level 3',target:3,value:()=>state.skills.Chinese,money:150,xp:40},
{id:'friend',title:'A familiar face',detail:'Make one close friend with a bond of 60',target:1,value:()=>Object.values(state.friends).filter(v=>v>=60).length,money:100,xp:50},
{id:'home',title:'A place of your own',detail:'Buy all three home upgrades',target:3,value:()=>['bed','kitchen','desk'].filter(id=>state.upgrades.includes(id)).length,money:300,xp:70},
{id:'founder',title:'Your first customers',detail:'Fulfil five studio orders',target:5,value:()=>state.stats.businessOrders,money:400,xp:80}
];
function dreamProgress(){const id=state.dream===''?0:+state.dream;const close=Object.values(state.friends).filter(v=>v>=60).length;if(id===1)return{done:close>=4,text:close+'/4 close friends'};if(id===2)return{done:!!state.business&&state.business.level>=3&&state.stats.businessOrders>=10,text:'Studio level '+(state.business?.level||0)+'/3 · '+state.stats.businessOrders+'/10 orders'};if(id===3)return{done:state.trips.length>=6,text:state.trips.length+'/6 cities visited'};return{done:level()>=5&&['bed','kitchen','desk'].every(id=>state.upgrades.includes(id)),text:'Player level '+level()+'/5 · '+state.upgrades.length+'/3 home upgrades'}}
function claimQuest(id){const q=quests.find(q=>q.id===id);if(!q||state.claimed.includes(id)||q.value()<q.target)return false;state.claimed.push(id);state.money+=q.money;state.xp+=q.xp;finish(q.title+' completed. Reward: ¥'+q.money+' and '+q.xp+' XP.');return true}
function claimDream(){const d=dreamProgress();if(!d.done||state.dreamClaimed)return false;state.dreamClaimed=true;state.money+=1000;state.xp+=150;finish('Dream achieved! You earned ¥1,000 and 150 XP.');return true}
function questsScreen(){const d=dreamProgress();screen('Your next chapter','Rewards can be claimed once. Follow your own pace.', '<div class="dream-card"><span class="eyebrow">YOUR DREAM</span><h3>'+dreams[state.dream===''?0:+state.dream][0]+'</h3><p>'+d.text+'</p>'+action('claimDream',state.dreamClaimed?'Dream achieved':d.done?'Claim ¥1,000 + 150 XP':'Keep building your story',state.dreamClaimed?'Reward collected':'Complete the dream to claim its reward')+'</div>'+quests.map(q=>'<div class="quest-card"><h3>'+q.title+'</h3><p>'+q.detail+'</p><progress max="'+q.target+'" value="'+Math.min(q.target,q.value())+'"></progress><span>'+Math.min(q.target,q.value())+'/'+q.target+' · ¥'+q.money+' + '+q.xp+' XP</span>'+action('quest-'+q.id,state.claimed.includes(q.id)?'Completed':q.value()>=q.target?'Claim reward':'In progress','One-time milestone')+'</div>').join(''));$('claimDream').disabled=!d.done||!!state.dreamClaimed;$('claimDream').onclick=()=>{claimDream();questsScreen()};quests.forEach(q=>{$('quest-'+q.id).disabled=state.claimed.includes(q.id)||q.value()<q.target;$('quest-'+q.id).onclick=()=>{claimQuest(q.id);questsScreen()}})}
const events=[
{title:'Language exchange at EFH',place:'ef',hour:18,cost:15,skill:'Chinese',story:'You taught someone a phrase from home and learnt two in Chinese.',options:['Join a conversation','Help a newcomer settle in']},
{title:'Campus creator challenge',place:'campus',hour:14,cost:0,skill:'Creativity',story:'Your short story about arriving in China found an audience.',options:['Share your story','Collaborate on a short video']},
{title:'Hunnan founder circle',place:'business',hour:16,cost:20,skill:'Network',story:'You met a potential client and practised introducing your idea.',options:['Pitch your studio idea','Ask for feedback']},
{title:'Basketball at Heping Gym',place:'gym',hour:17,cost:15,skill:'Fitness',story:'Your team found a rhythm. You left with an invitation to play again.',options:['Play a match','Help organise the game']},
{title:'Open mic at Foreigners’ Night',place:'night',hour:20,cost:35,skill:'Creativity',story:'The room cheered. Another small step toward feeling at home.',options:['Perform on stage','Support a new performer']},
{title:'Saturday lakeside meetup',place:'park',hour:11,cost:0,skill:'Social',story:'A walk by the lake turned into a long conversation.',options:['Join the walking group','Start a conversation']},
{title:'Market food discovery',place:'market',hour:12,cost:12,skill:'Chinese',story:'You tried something new and ordered it with confidence.',options:['Practise ordering','Learn a recipe from the vendor']}
];
function currentEvent(){const e=events[(state.day-1)%events.length],titles={ef:'Language exchange',campus:'Creator challenge',business:'Founder circle',gym:'Basketball',night:'Open mic',park:'Community meetup',market:'Food discovery'};return {...e,title:titles[e.place]+' · '+L.find(p=>p[0]===e.place)[1]}}
function attendEvent(choice){if(![0,1].includes(choice))return false;const day=state.day,e=currentEvent();if(state.eventHistory[day]!==undefined)return false;if(state.place!==e.place){toast('Travel to '+L.find(l=>l[0]===e.place)[1]+' first.');return false}if(state.hour<e.hour*60||state.hour>e.hour*60+180){toast('This event runs from '+e.hour+':00 to '+(e.hour+3)+':00.');return false}if((e.cost>0&&state.money<e.cost)||state.needs.energy<15){toast('You need ¥'+e.cost+' and at least 15 energy.');return false}if(!runningCallback&&window.ChinaLifeWorld){sceneAction({kind:e.place==='gym'?'basketball':e.place==='night'?'perform':'talk',x:0,z:2,label:e.title},()=>attendEvent(choice));return false}state.money-=e.cost;state.eventHistory[day]=choice;state.needs.energy-=15;state.needs.fun=Math.min(100,state.needs.fun+20);state.needs.social=Math.min(100,state.needs.social+25);gain(choice===1?'Social':e.skill,30);state.xp+=25;advance(90);finish(e.story);return true}
function eventScreen(){const e=currentEvent();const done=state.eventHistory[state.day]!==undefined;screen(e.title,'Day '+state.day+' · '+e.hour+':00–'+(e.hour+3)+':00 · '+L.find(l=>l[0]===e.place)[1]+' · ¥'+e.cost, '<p>City events rotate each game day. You can attend once per day.</p>'+action('eventTravel','Go to the venue','Choose transport on the city map')+e.options.map((o,i)=>action('eventChoice'+i,done?'Attended today':o,'90 minutes · 25 XP · skill and social boosts')).join(''));$('eventTravel').onclick=()=>{$('activityDialog').close();select(e.place)};e.options.forEach((o,i)=>{$('eventChoice'+i).disabled=done;$('eventChoice'+i).onclick=()=>{if(attendEvent(i))eventScreen()}})}
function businessFeedback(message){const status=$('businessStatus');if(status&&$('activityDialog').open)status.textContent=message;else toast(message)}
function launchBusiness(){if(state.business)return false;if(state.skills.Network<2||state.skills.Digital<2){businessFeedback('Train Network and Digital to level 2 first. Your levels: Network '+state.skills.Network+' · Digital '+state.skills.Digital+'.');return false}if(state.money<900){businessFeedback('Opening a studio costs ¥900. Your balance is ¥'+state.money.toLocaleString()+'.');return false}state.money-=900;state.business={level:1,orders:0,revenue:0,lastOrder:0};finish('Your small creative studio is open. Your first client is waiting.');return true}
function fulfilOrder(){const b=state.business;if(!b||b.lastOrder===state.day)return false;if(state.place!=='business'){businessFeedback('Go to '+L.find(p=>p[0]==='business')[1]+' to fulfil this order.');return false}if(state.needs.energy<25||state.needs.hunger<20){businessFeedback('Eat and rest before taking a client order. You need 25 energy and 20 hunger.');return false}if(!runningCallback&&window.ChinaLifeWorld){if(window.ChinaLifeWorld.busy){businessFeedback('Finish your current action first.');return false}$('activityDialog').close();sceneAction({kind:'type',x:0,z:-.5,label:'Working on your client order'},()=>fulfilOrder());return false}const pay=180+b.level*90;b.lastOrder=state.day;b.orders++;b.revenue+=pay;state.stats.businessOrders++;state.money+=pay;state.needs.energy-=25;state.needs.hunger-=15;advance(180);gain('Digital',25);gain('Network',15);state.xp+=30;finish('Client order delivered. Your studio earned ¥'+pay+'.');return true}
function growBusiness(){const b=state.business;if(!b||b.level>=3)return false;const cost=b.level*1000,required=b.level*3;if(b.orders<required||state.money<cost){businessFeedback('You need '+required+' orders and ¥'+cost+' to expand. You have '+b.orders+' orders and ¥'+state.money.toLocaleString()+'.');return false}state.money-=cost;b.level++;finish('Studio expanded to level '+b.level+'. Client orders now pay more.');return true}
function businessScreen(){const b=state.business;screen(b?'Your creative studio':'Start something of your own',b?'Level '+b.level+'/3 · '+b.orders+' orders · ¥'+b.revenue+' total revenue':'Open a fictional creative studio at Hunnan. Train Network and Digital at the hub and café.',b? action('businessTravel','Go to your studio','Hunnan Startup Hub')+action('businessOrder',b.lastOrder===state.day?'Today’s order delivered':'Fulfil a client order','3 hours · earns ¥'+(180+b.level*90)+' · one order per day')+action('businessExpand',b.level===3?'Studio fully expanded':'Expand your studio','Requires '+(b.level*3)+' total orders and ¥'+(b.level*1000)):action('businessLaunch','Open your studio · ¥900','Requires Network level 2 and Digital level 2'));$('activityContent').insertAdjacentHTML('beforeend','<p id="businessStatus" class="panel-feedback" role="status" aria-live="polite"></p>');if(b){$('businessTravel').onclick=()=>{$('activityDialog').close();select('business')};$('businessOrder').disabled=b.lastOrder===state.day;$('businessOrder').onclick=()=>{fulfilOrder()};$('businessExpand').disabled=b.level>=3;$('businessExpand').onclick=()=>{if(growBusiness()){businessScreen();businessFeedback('Studio expanded. Your client orders now pay more.')}}}else $('businessLaunch').onclick=()=>{if(launchBusiness()){businessScreen();businessFeedback('Your studio is open. Go to the hub to deliver your first order.')}}}
function render(){ensure();rankUp();checkSecrets();checkCertificates();renderBase();survival();reminders();if(state.job){$('agenda').innerHTML='<b>Career level '+state.promotion+'/5</b><button class="soft-btn" id="workBtn">Work a shift</button>';$('workBtn').onclick=shiftScreen}if(selected==='home'){$('panelContent').insertAdjacentHTML('beforeend','<div class="panel-content"><button class="soft-btn" id="manageHome">Manage home</button></div>');$('manageHome').onclick=homeScreen}$('pulseGrid').innerHTML='<button class="pulse-card pulse-action" id="questsCard"><span class="eyebrow">YOUR GOALS</span><strong>'+quests.filter(q=>!state.claimed.includes(q.id)&&q.value()>=q.target).length+' rewards ready</strong><p>Quests, milestones and your dream.</p></button><button class="pulse-card pulse-action" id="eventCard"><span class="eyebrow">TODAY’S EVENT</span><strong>'+currentEvent().title+'</strong><p>'+currentEvent().hour+':00 · '+(state.eventHistory[state.day]!==undefined?'Attended':'Open today')+'</p></button><button class="pulse-card pulse-action" id="businessCard"><span class="eyebrow">YOUR BUSINESS</span><strong>'+(state.business?'Creative studio · Level '+state.business.level:'Start your own studio')+'</strong><p>'+(state.business?state.business.orders+' orders delivered':'Build skills and meet your first client.')+'</p></button>';$('questsCard').onclick=questsScreen;$('eventCard').onclick=eventScreen;$('businessCard').onclick=businessScreen;$('needsBtn').onclick=()=>screen('Keep your needs balanced','Activities change your needs. Rest, eat and freshen up before a shift.',needs.map(n=>'<p>'+names[n]+': '+state.needs[n]+'%</p>').join(''));$('cityBtn').onclick=tripScreen;window.dispatchEvent(new CustomEvent('chinalife:update'))}
